const input = require("fs").readFileSync(0, "utf8");

function sumOfDigitSquares(n) {
  let total = 0;
  while (n > 0) {
    const digit = n % 10;
    total += digit * digit;
    n = Math.floor(n / 10);
  }
  return total;
}

function isHappy(n) {
  const seen = new Set();
  while (n !== 1 && !seen.has(n)) {
    seen.add(n);
    n = sumOfDigitSquares(n);
  }
  return n === 1;
}

const n = Number(input.trim());
console.log(isHappy(n) ? "true" : "false");

