#include <iostream>
#include <unordered_set>

int sumOfDigitSquares(int n) {
    int total = 0;
    while (n > 0) {
        int digit = n % 10;
        total += digit * digit;
        n /= 10;
    }
    return total;
}

bool isHappy(int n) {
    std::unordered_set<int> seen;
    while (n != 1 && seen.count(n) == 0) {
        seen.insert(n);
        n = sumOfDigitSquares(n);
    }
    return n == 1;
}

int main() {
    int n;
    std::cin >> n;
    std::cout << (isHappy(n) ? "true" : "false") << "\n";
    return 0;
}

